import Axios from '@/server'
import type { Result } from '@/server/types'
import { AdvertisementTypes } from './types'

/**
 * 获取广告列表
 * @param params 查询参数
 */
export const getAdvertisementList = (params?: AdvertisementTypes.AdvertisementListReq) =>
  Axios.request<Result<AdvertisementTypes.AdvertisementListRes>>({
    url: '/admin/advertisement-management/list',
    method: 'GET',
    params
  })

/**
 * 获取广告详情
 * @param id 广告ID
 */
export const getAdvertisementDetail = (id: number) =>
  Axios.request<Result<AdvertisementTypes.DetailAdvertisementRes>>({
    url: `/admin/advertisement-management/${id}/detail`,
    method: 'GET'
  })

/**
 * 添加广告
 * @param data 广告信息
 */
export const addAdvertisement = (data: AdvertisementTypes.AddAdvertisementReq) =>
  Axios.request<Result>({
    url: '/admin/advertisement-management/add',
    method: 'POST',
    data
  })

/**
 * 编辑广告
 * @param id 广告ID
 * @param data 广告信息
 */
export const editAdvertisement = (id: number, data: AdvertisementTypes.EditAdvertisementReq) =>
  Axios.request<Result>({
    url: `/admin/advertisement-management/${id}/edit`,
    method: 'POST',
    data
  })

/**
 * 删除广告
 * @param id 广告ID
 * @param data 请求参数
 */
export const deleteAdvertisement = (id: number, data: AdvertisementTypes.DeletedAdvertisementReq) =>
  Axios.request<Result>({
    url: `/admin/advertisement-management/${id}/deleted`,
    method: 'POST',
    data
  })

/**
 * 广告管理类型命名空间
 * @example
 * ```typescript
 * import { advertisementApi } from '@/apis';
 * const params: advertisementApi.AdvertisementTypes.AdvertisementListReq = { page: 1 };
 * ```
 */
export type { AdvertisementTypes }
