import { useRef, useState, useEffect } from 'react'
import {
  getAdvertisementList,
  addAdvertisement,
  editAdvertisement,
  deleteAdvertisement,
  AdvertisementTypes
} from '@/apis/admin/advertisement'
import { uploadImage } from '@/apis/admin/site'
import { ActionType, ProColumns, ProTable } from '@ant-design/pro-components'
import {
  Button,
  Popconfirm,
  message,
  Tag,
  Space,
  Modal,
  Form,
  Input,
  Select,
  InputNumber,
  DatePicker,
  Upload,
  Image,
  Tooltip
} from 'antd'
import {
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  UploadOutlined,
  EyeOutlined,
  InfoCircleOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'
import type { UploadFile, UploadProps } from 'antd/es/upload/interface'

// 平台映射
const platformMap: Record<number, { text: string; color: string }> = {
  1: { text: 'XLINK', color: 'blue' },
  2: { text: 'AIPOST', color: 'green' }
}

// 跳转类型映射
const jumpTypeMap: Record<number, string> = {
  1: 'H5链接',
  2: '小程序内部',
  3: '无跳转'
}

// 获取广告状态（基于时间自动计算）
const getAdStatus = (startTime: string, endTime: string): { text: string; color: string } => {
  const now = dayjs()
  const start = dayjs(startTime)
  const end = dayjs(endTime)

  if (now.isBefore(start)) {
    return { text: '待上线', color: 'warning' }
  } else if (now.isAfter(end)) {
    return { text: '已下线', color: 'default' }
  }
  return { text: '已上线', color: 'success' }
}

const AdList: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const [modalVisible, setModalVisible] = useState(false)
  const [modalTitle, setModalTitle] = useState('新增广告')
  const [editingId, setEditingId] = useState<number | null>(null)
  const [form] = Form.useForm()
  const [fileList, setFileList] = useState<UploadFile[]>([])
  const [imageUrl, setImageUrl] = useState('')
  const [loading, setLoading] = useState(false)

  // 表格列定义
  const columns: ProColumns<AdvertisementTypes.AdvertisementListDto>[] = [
    {
      title: '广告ID',
      dataIndex: 'id',
      key: 'id',
      width: 80,
      search: false,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '广告标题',
      dataIndex: 'title',
      key: 'title',
      width: 180,
      ellipsis: true
    },
    {
      title: '所属端',
      dataIndex: 'platform',
      key: 'platform',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: 'XLINK' },
        2: { text: 'AIPOST' }
      },
      render: (_, record) => {
        const platform = platformMap[record.platform]
        return <Tag color={platform?.color}>{platform?.text}</Tag>
      }
    },
    {
      title: '广告图片',
      dataIndex: 'imageUrl',
      key: 'imageUrl',
      width: 120,
      search: false,
      render: text =>
        text ? (
          <Image
            src={text as string}
            alt="广告图"
            style={{ width: 88, height: 40, objectFit: 'cover', borderRadius: 4 }}
            preview={{ mask: <EyeOutlined /> }}
          />
        ) : (
          <div
            style={{
              width: 88,
              height: 40,
              borderRadius: 4,
              background: 'linear-gradient(120deg, #DBEAFE, #BFDBFE)',
              border: '1px solid #93C5FD',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#1D4ED8',
              fontSize: 11
            }}
          >
            无图片
          </div>
        )
    },
    {
      title: '跳转链接',
      dataIndex: 'jumpUrl',
      key: 'jumpUrl',
      width: 180,
      ellipsis: true,
      search: false,
      render: text => text || '-'
    },
    {
      title: '跳转类型',
      dataIndex: 'jumpType',
      key: 'jumpType',
      width: 120,
      search: false,
      render: text => jumpTypeMap[text as number] || '-'
    },
    {
      title: '排序值',
      dataIndex: 'sort',
      key: 'sort',
      width: 80,
      search: false,
      render: text => <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
    },
    {
      title: '生效时间',
      key: 'timeRange',
      width: 180,
      search: false,
      render: (_, record) => (
        <div style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
          <div>{dayjs(record.startTime).format('YYYY-MM-DD HH:mm')}</div>
          <div style={{ color: '#999' }}>{dayjs(record.endTime).format('YYYY-MM-DD HH:mm')}</div>
        </div>
      )
    },
    {
      title: '状态',
      key: 'status',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '已上线' },
        2: { text: '待上线' },
        3: { text: '已下线' }
      },
      render: (_, record) => {
        const status = getAdStatus(record.startTime, record.endTime)
        return <Tag color={status.color}>{status.text}</Tag>
      }
    },
    {
      title: '创建时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 160,
      search: false,
      render: text => dayjs(text as string).format('YYYY-MM-DD HH:mm:ss')
    },
    {
      title: '操作',
      key: 'action',
      width: 150,
      fixed: 'right',
      search: false,
      render: (_, record) => (
        <Space>
          <Tooltip title="编辑">
            <Button type="link" icon={<EditOutlined />} onClick={() => handleEdit(record)} />
          </Tooltip>
          <Popconfirm
            title="确认删除"
            description={`确定要删除广告「${record.title}」吗？`}
            onConfirm={() => handleDelete(record)}
            okText="确认"
            cancelText="取消"
          >
            <Tooltip title="删除">
              <Button type="link" danger icon={<DeleteOutlined />} />
            </Tooltip>
          </Popconfirm>
        </Space>
      )
    }
  ]

  // 打开新增弹窗
  const handleAdd = () => {
    setEditingId(null)
    setModalTitle('新增广告')
    form.resetFields()
    setImageUrl('')
    setFileList([])
    setModalVisible(true)
  }

  // 打开编辑弹窗
  const handleEdit = (record: AdvertisementTypes.AdvertisementListDto) => {
    setEditingId(record.id)
    setModalTitle(`编辑广告 - ${record.id}`)
    form.setFieldsValue({
      title: record.title,
      platform: record.platform,
      jumpType: record.jumpType,
      jumpUrl: record.jumpUrl,
      sort: record.sort,
      startTime: dayjs(record.startTime),
      endTime: dayjs(record.endTime)
    })
    setImageUrl(record.imageUrl)
    if (record.imageUrl) {
      setFileList([{ uid: '-1', name: 'image.png', status: 'done', url: record.imageUrl }])
    } else {
      setFileList([])
    }
    setModalVisible(true)
  }

  // 删除广告
  const handleDelete = async (record: AdvertisementTypes.AdvertisementListDto) => {
    try {
      const res = await deleteAdvertisement(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('删除成功')
        actionRef.current?.reload()
      } else {
        message.error('删除失败')
      }
    } catch (e) {
      console.error('删除广告失败:', e)
      message.error('删除失败')
    }
  }

  // 提交表单
  const handleSubmit = async () => {
    try {
      const values = await form.validateFields()
      setLoading(true)

      const params = {
        title: values.title,
        platform: values.platform,
        imageUrl: imageUrl,
        jumpUrl: values.jumpUrl,
        sort: values.sort,
        startTime: values.startTime.format('YYYY-MM-DD HH:mm:ss'),
        endTime: values.endTime.format('YYYY-MM-DD HH:mm:ss'),
        jumpType: values.jumpType
      }

      let res
      if (editingId) {
        res = await editAdvertisement(editingId, { id: editingId, ...params })
      } else {
        res = await addAdvertisement(params)
      }

      if (res.code === ResultEnum.SUCCESS) {
        message.success(editingId ? '编辑成功' : '新增成功')
        setModalVisible(false)
        actionRef.current?.reload()
      } else {
        message.error(editingId ? '编辑失败' : '新增失败')
      }
    } catch (e) {
      console.error('提交表单失败:', e)
    } finally {
      setLoading(false)
    }
  }

  // 图片上传配置
  const uploadProps: UploadProps = {
    name: 'file',
    listType: 'picture-card',
    fileList: fileList,
    showUploadList: true,
    beforeUpload: async file => {
      const isJpgOrPng =
        file.type === 'image/jpeg' ||
        file.type === 'image/jpg' ||
        file.type === 'image/png' ||
        file.type === 'image/gif'
      if (!isJpgOrPng) {
        message.error('只支持 JPG/PNG/GIF 格式的图片!')
        return Upload.LIST_IGNORE
      }
      const isLt2M = file.size / 1024 / 1024 < 2
      if (!isLt2M) {
        message.error('图片大小不能超过 2MB!')
        return Upload.LIST_IGNORE
      }
      return true
    },
    customRequest: async ({ file, onSuccess, onError }) => {
      try {
        const formData = new FormData()
        formData.append('file', file)
        formData.append('bizType', 'ads')
        const res = await uploadImage(formData)
        if (res.code === ResultEnum.SUCCESS && res.data?.url) {
          setImageUrl(res.data.url)
          setFileList([{ uid: '-1', name: (file as File).name, status: 'done', url: res.data.url }])
          onSuccess?.(res.data)
          message.success('上传成功')
        } else {
          onError?.(new Error('上传失败'))
          message.error('上传失败')
        }
      } catch (e) {
        onError?.(e as Error)
        message.error('上传失败')
      }
    },
    onRemove: () => {
      setImageUrl('')
      setFileList([])
    }
  }

  // 获取图片尺寸提示
  const getImageHint = (platform?: number) => {
    if (platform === 1) {
      return 'XLINK 建议 828x360px，jpg/png/gif，单张不超过 2MB'
    }
    return 'AIPOST 建议 750x340px，jpg/png/gif，单张不超过 2MB'
  }

  const platformValue = Form.useWatch('platform', form)

  return (
    <div>
      <ProTable<AdvertisementTypes.AdvertisementListDto>
        headerTitle="广告列表"
        actionRef={actionRef}
        rowKey="id"
        search={{
          labelWidth: 'auto'
        }}
        toolBarRender={() => [
          <Button key="add" type="primary" icon={<PlusOutlined />} onClick={handleAdd}>
            新增广告
          </Button>
        ]}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        request={async params => {
          const res = await getAdvertisementList({
            page: params.current,
            pageSize: params.pageSize,
            title: params.title,
            platform: params.platform,
            status: params.status
          })
          if (res.code === ResultEnum.SUCCESS && res.data) {
            return {
              data: res.data.list,
              success: true,
              total: res.data.totalCount
            }
          }
          return { data: [], success: false, total: 0 }
        }}
        columns={columns}
        pagination={{
          showQuickJumper: true,
          showSizeChanger: true,
          defaultPageSize: 10
        }}
      />

      <Modal
        title={modalTitle}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        onOk={handleSubmit}
        confirmLoading={loading}
        width={720}
        destroyOnClose
      >
        <Form
          form={form}
          layout="horizontal"
          labelCol={{ span: 6 }}
          wrapperCol={{ span: 18 }}
          autoComplete="off"
          style={{ marginTop: 16 }}
        >
          <Form.Item
            label="广告标题"
            name="title"
            rules={[{ required: true, message: '请输入广告标题' }]}
          >
            <Input placeholder="请输入广告标题" maxLength={50} showCount />
          </Form.Item>

          <Form.Item
            label="所属端"
            name="platform"
            initialValue={2}
            rules={[{ required: true, message: '请选择所属端' }]}
          >
            <Select
              placeholder="请选择所属端"
              options={[
                { label: 'XLINK', value: 1 },
                { label: 'AIPOST', value: 2 }
              ]}
            />
          </Form.Item>

          <Form.Item
            label="跳转类型"
            name="jumpType"
            initialValue={3}
            rules={[{ required: true, message: '请选择跳转类型' }]}
          >
            <Select
              placeholder="请选择跳转类型"
              options={[
                { label: 'H5链接', value: 1 },
                { label: '小程序内部', value: 2 },
                { label: '无跳转', value: 3 }
              ]}
            />
          </Form.Item>

          <Form.Item label="跳转链接" name="jumpUrl">
            <Input placeholder="https:// 或 /pages/" />
          </Form.Item>

          <Form.Item label="排序值" name="sort" >
            <InputNumber min={0} max={999} style={{ width: '100%' }} />
          </Form.Item>

          <Form.Item
            label="生效起始时间"
            name="startTime"
            rules={[{ required: true, message: '请选择生效起始时间' }]}
          >
            <DatePicker
              showTime
              format="YYYY-MM-DD HH:mm:ss"
              style={{ width: '100%' }}
              placeholder="请选择生效起始时间"
            />
          </Form.Item>

          <Form.Item
            label="生效结束时间"
            name="endTime"
            rules={[{ required: true, message: '请选择生效结束时间' }]}
          >
            <DatePicker
              showTime
              format="YYYY-MM-DD HH:mm:ss"
              style={{ width: '100%' }}
              placeholder="请选择生效结束时间"
            />
          </Form.Item>

          <Form.Item
            label="广告图片"
            required
            tooltip={{
              title: getImageHint(platformValue),
              icon: <InfoCircleOutlined />
            }}
          >
            <Upload {...uploadProps}>
              {fileList.length >= 1 ? null : (
                <div>
                  <UploadOutlined />
                  <div style={{ marginTop: 8 }}>上传图片</div>
                </div>
              )}
            </Upload>
            <div style={{ color: '#999', fontSize: 12, marginTop: 8 }}>
              {getImageHint(platformValue)}
            </div>
          </Form.Item>
        </Form>

        <div
          style={{
            padding: 12,
            background: '#F8FAFC',
            borderRadius: 8,
            marginTop: 16,
            marginBottom: 16
          }}
        >
          <div style={{ fontSize: 13, color: '#64748B', marginBottom: 4 }}>
            <InfoCircleOutlined style={{ marginRight: 6, color: '#2563EB' }} />
            状态自动判断规则
          </div>
          <div style={{ fontSize: 12, color: '#94A3B8' }}>
            待上线：当前时间 &lt; 生效起始时间 | 已上线：生效起始时间 ≤ 当前时间 ≤ 生效结束时间 |
            已下线：当前时间 &gt; 生效结束时间
          </div>
        </div>
      </Modal>
    </div>
  )
}

export default AdList
